using MediatR; using PartyNL.Application.Abstractions.Repositories; using PartyNL.Domain.Enums;
namespace PartyNL.Application.Features.Events.Queries.GetEventById;
public sealed record GetEventByIdQuery(Guid EventId):IRequest<GetEventByIdResponse>;public sealed record GetEventByIdResponse(Guid Id,Guid OrganizerId,Guid LocationId,string Title,string? Description,DateTime StartDate,DateTime EndDate,decimal Price,int Capacity,int MinimumAge,EventVisibility Visibility,EventStatus Status,string? CoverImageUrl);
public sealed class GetEventByIdHandler(IEventRepository repository):IRequestHandler<GetEventByIdQuery,GetEventByIdResponse>{public async Task<GetEventByIdResponse> Handle(GetEventByIdQuery request,CancellationToken cancellationToken){var e=await repository.GetByIdAsync(request.EventId)??throw new KeyNotFoundException($"Event with ID '{request.EventId}' was not found.");return new(e.Id,e.OrganizerId,e.LocationId,e.Title,e.Description,e.StartDate,e.EndDate,e.Price,e.Capacity,e.MinimumAge,e.Visibility,e.Status,e.CoverImageUrl);}}